local Vendor = require "ejoysdk_lua.vendors.vendor"
local EV = require "ejoysdk_lua.ejoysdk_vendors"
local VENDOR_NAME = 'WIN_OVERSEAS_PAY'
local EM = require "ejoysdk_lua.ejoysdk_module"
local CONSTANTS = require "ejoysdk_lua.ejoysdk_constants"
local E = require "ejoysdk_lua.ejoysdk"
local EG = require 'ejoysdk_lua.ejoysdk_gangplank'

local M = Vendor:Inherit(VENDOR_NAME)

local TAG = EM.MODULE.VENDORS.WIN_OVERSEAS_PAY

local initted = false

-- H5页面支付状态
local H5_PAY_STATE = {
    DEFAULT = 0,
    SUCCESS = 1,    -- 成功
    FAILED = 2,     -- 失败
    REFUND = 3      -- 退款
}

function M.init(_opt, cb)
    E.LOG.debug(TAG, "init begin")

    if initted then
        E.LOG.debug(TAG, "already initted, and return")
        if cb then
            cb(true)
        end
        return
    end

    initted = true

    if cb then
        cb(initted)
    end
end

-- 打开支付中心页面
local function open_pay_center_webview(url, pay_params, error_params, cb)

    local pay_finished = false

    local last_pay_status
    local on_js_callback = function(_value)
        local args = _value.args
        E.LOG.debug(TAG, "open_pay_center_webview js callback >>")
        E.LOG.debug(TAG, args)

        --[[
            返回示例：
            {
               ["params"] => table: 0C13CFB8{
                  ["msg"] => "初始"
                  ["serverCode"] => 200000
                  ["orderStatus"] => -0
               }
               ["type"] => "win_pay_center_pay_result"
            }
        --]]
        if args.type == 'win_pay_center_pay_result' then

            -- 缓存支付状态
            last_pay_status = args.params or {}

            pay_finished = true
        end
    end

    local on_close_callback = function()
        E.LOG.debug(TAG, "open_pay_center_webview close callback >>")

        local order_id = (pay_params or {}).cpOrderId
        if pay_finished then
            E.LOG.debug(TAG, "pay finished and webview is closed, last_pay_status >>")
            E.LOG.debug(TAG, last_pay_status)

            -- check pay result
            last_pay_status = last_pay_status or {}
            local orderStatus = last_pay_status.orderStatus
            if orderStatus == H5_PAY_STATE.SUCCESS then
                E.LOG.debug(TAG, "receive pay succ")
                cb(true,order_id)
            else
                local msg = last_pay_status.msg
                local code = last_pay_status.serverCode
                E.LOG.warn(TAG, "receive pay failed, code:" .. tostring(code) .. ", msg:" .. tostring(msg))
                cb(false, order_id,{code=code,msg=msg})
            end
        else
            E.LOG.warn(TAG, "pay cancelled")
            cb(false,order_id,{code=CONSTANTS.OFFICIAL_ERR_CODES.CODE_PAY_CANCEL, msg="pay cancelled"})
        end
    end

    local trd_params = {}
    local init_args = E.CONFIG.get_config(E.CONFIG.KEY.INIT_ARGS)
    if type(init_args) == 'table' and next(init_args) and type(init_args.channel) == 'string' then
        local channel = string.upper(init_args.channel)
        local channel_vendor = EV.get(channel)
        if channel_vendor and channel_vendor.check_args then
            local params = channel_vendor.check_args(init_args)
            trd_params = params or trd_params
            trd_params.type = (EG.user_info() or {}).platform -- 三方渠道类型，与登录相关
        end
    end

    local product_info = pay_params or {}
    local start_up_data = {
        product_info = product_info,
        cp_order_id = product_info.cpOrderId, -- 跟安卓的虚拟支付协议对齐
        gp_order_id = product_info.gpOrderId, -- 在PC的海外支付里，cp_order_id是official_order的id，gp_order_id是gangplank的订单id
        order_amount = tonumber(product_info.showMoney),
        product_name = product_info.payProductName,
        pay_error_data = error_params,
        sysinfo_country = E.CONFIG.get_config('district'),
        thirdparty_params = trd_params
    }

    local options = {
        hide_close_btn = false,
        min_width = 450,
        min_height = 400,
        transparent = true
    }

    -- 从url里，提取域名
    local url_white_hosts = {}
    local ret = E.HTTP.parse(url)
    if ret.host then
        table.insert(url_white_hosts, ret.host)
    end

    E.LOG.d(TAG, 'will open pay h5, params >>')
    E.LOG.d(TAG, {
        url = url,
        url_white_hosts = url_white_hosts,
        start_up_data = start_up_data,
        options = options
    })

    E.open_webview_with_options(url, url_white_hosts, start_up_data, options, on_js_callback, on_close_callback)
end

local function get_pay_url()
    local url

    -- 从gangplank-config里取
    local EGC = require 'ejoysdk_lua.ejoysdk_gangplank_config'
    local gangplank_config = EGC.get_current_cdn_config()
    if gangplank_config and gangplank_config.render_center and gangplank_config.render_center.payment and ''~= gangplank_config.render_center.payment then
        url = gangplank_config.render_center.payment
    end

    E.LOG.d(TAG, 'get_pay_url, ret=' .. tostring(url))
    return url
end

-- 注意：ext_info不要去改，支付SDK会验签的，改了会验签失败，导致不能支付。
-- local_params是平台H5支付用到的扩展信息，可以修改。
function M.pay(product_id, count, order_id, _ext_info, cb, local_params)
    E.LOG.d(TAG, 'start pay, params >>')
    E.LOG.d(TAG, {
        product_id = product_id,
        count = count,
        order_id = order_id,
        ext_info = _ext_info,
        local_params = local_params,
        cb = type(cb)
    })

    -- 防护一下，防止local_params是nil
    local_params = local_params or {}
    local gp_order_id = local_params.gp_order_id

    if not product_id then
        E.LOG.warn(TAG, 'product id not exist')
        cb(false, gp_order_id, {code=CONSTANTS.OFFICIAL_ERR_CODES.CODE_PAY_PRODUCT_ID_NOT_EXIST, msg='product id not exist'})
        return
    end

    if not order_id then
        E.LOG.warn(TAG, 'order id not exist')
        cb(false, gp_order_id, {code=CONSTANTS.OFFICIAL_ERR_CODES.CODE_PAY_ORDER_ID_NOT_EXIST, msg='order id not exist'})
        return
    end

    local url = get_pay_url()
    if not url or url == '' then
        E.LOG.warn(TAG, 'pay h5 url not config')
        cb(false, gp_order_id, {code=CONSTANTS.OFFICIAL_ERR_CODES.CODE_PAY_WEB_URL_NOT_CONFIG, msg='pay h5 url not config'})
        return
    end

    local product = local_params.product_info
    if not product then
        E.LOG.warn(TAG, 'pay product not exist')
        cb(false, gp_order_id, {code=CONSTANTS.OFFICIAL_ERR_CODES.CODE_PAY_PRODUCT_NOT_EXIST, msg='pay product not exist'})
        return
    end

    local pay_params = {
        cpOrderId = order_id,
        gpOrderId = local_params.gp_order_id,
        amount = product.money,
        showMoney = product.show_money,
        moneyType = product.money_type,
        payProductID = product.product_id,
        payProductName = product.product_desc,
        payProductDescribe = product.product_desc,
        -- product_type没有就默认是消费型  https://yuque.antfin-inc.com/ejoy-platform/ejoy-platform/oevt5u#HGxIK
        payProductType = product.product_type or 1,
    }

    open_pay_center_webview(url, pay_params, nil, cb)
end

function M.skip_official_order()
    -- 是否需要海外支付下单
    local res = false
    E.LOG.debug(TAG, "skip_official_order=" .. tostring(res))
    return res
end

function M.skip_gp_order()
    -- 是否需要gangplank下单
    local res = false
    E.LOG.debug(TAG, "skip_gp_order=" .. tostring(res))
    return res
end

return M